async function replaySuffix(request, onto) {
  try {
    const { stdout, stderr } = await exec(process.execPath, [
      rebaseCli,
      "rebase",
      "--onto",
      onto,
      "--ref",
      request.startingRevision,
      "--branch",
      request.branch,
      "--cwd",
      request.workspace,
      "--file",
      pathOf(request),
    ]);
    return { code: 0, stdout, stderr };
  } catch (error) {
